import {
  CheckCircle2,
  XCircle,
  Lightbulb,
  MousePointerClick,
  Shield,
  Eye,
  Smartphone,
  PenLine,
  Gauge,
  Clock,
  Brain,
  Zap,
} from "lucide-react";
import { Card, CardContent } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
