  },
  {
    icon: Shield,
    label: "Trust Signals",
    weight: "17%",
    description:
      "Testimonials, star ratings, security badges, client logos, and third-party validation — we check for presence, placement, and credibility.",
  },
  {
    icon: Eye,
    label: "Visual Hierarchy",
    weight: "12%",
    description:
      "Eye flow from headline to subheading to CTA, section ordering, whitespace usage, and whether the page guides attention toward conversion.",
