  {
    icon: Smartphone,
    label: "Mobile Experience",
    weight: "13%",
    description:
      "Tap target sizing, responsive breakpoints, mobile font sizing, and how the conversion path changes on small screens.",
  },
  {
    icon: PenLine,
    label: "Content & Copy",
    weight: "11%",
    description:
      "Headline strength, benefit-vs-feature ratio, reading level, clarity, and whether your copy matches the search intent of your visitors.",
  },
  {
    icon: Gauge,
    label: "Page Performance",
    weight: "9%",
    description:
      "Largest Contentful Paint, Cumulative Layout Shift, First Input Delay, and Google PageSpeed score — all via real measurements.",
  },
];

const STEPS = [
  {
    number: "1",
    icon: Clock,
    title: "Paste your URL",
    description: "Drop any landing page, product page, or homepage URL into the input. No code, no browser extension, no setup.",
  },
  {
    number: "2",
    icon: Brain,
    title: "AI analyzes 40+ signals",
    description: "Our AI captures a screenshot, runs PageSpeed measurements, and checks every pillar against 40+ conversion best practices simultaneously.",
  },
  {
    number: "3",
    icon: Zap,
    title: "Get your prioritized fix list",
    description: "Results arrive in under 30 seconds: a scored breakdown by pillar plus a ranked list of issues ordered by conversion impact.",
  },
];

const COMPARISON_ROWS: Array<{ check: string; manual: boolean; tool: boolean }> = [
  { check: "Time to first finding", manual: false, tool: true },
  { check: "Consistent scoring across auditors", manual: false, tool: true },
  { check: "PageSpeed data included", manual: false, tool: true },
  { check: "AI-generated fix suggestions", manual: false, tool: true },
