  {
    question: "How is this different from Google Analytics?",
    answer:
      "Google Analytics tells you what is happening — bounce rate, session duration, exit rate. ConvertScan tells you why it's happening. Rather than showing you that 70% of visitors leave without converting, we show you that your CTA has low contrast, your mobile load time is 4.8 seconds, and your headline is feature-focused rather than outcome-focused. Analytics identifies the symptom; ConvertScan diagnoses the cause.",
  },
  {
    question: "Can I analyze competitor landing pages?",
    answer:
      "Yes. ConvertScan works on any publicly accessible URL. Many teams audit competitor pages to benchmark their own conversion setup against industry leaders. You can see exactly how a competitor's page scores across each pillar and get insight into what's making their pages work.",
  },
  {
    question: "How quickly will I see results after implementing fixes?",
    answer:
      "Simple fixes like improving CTA button contrast or moving the button above the fold typically show measurable impact within 1–2 weeks of traffic. Larger changes like rewriting headlines benefit from A/B testing over 2–4 weeks. Our score monitoring feature (Pro and above) tracks your score over time so you can see the impact of every change.",
  },
  {
    question: "Do you analyze landing page copy quality?",
    answer:
      "Yes. Our AI reads your headline, subheading, and body copy and evaluates it for outcome orientation (does it lead with benefits or features?), specificity (vague claims vs. concrete numbers), reading level appropriateness, benefit-to-feature ratio, and whether it addresses common objections. You get specific suggestions for rewriting weak copy sections.",
  },
];

/* ── Section wrapper ─────────────────────────────────────────── */

function AnimatedSection({
  children,
  className = "",
}: {
  children: React.ReactNode;
  className?: string;
}) {
  const ref = useRef<HTMLDivElement>(null);
  const isInView = useInView(ref, { once: true, margin: "-80px" });
  return (
    <motion.div
      ref={ref}
      initial="hidden"
      animate={isInView ? "show" : "hidden"}
      variants={stagger}
      className={className}
    >
      {children}
    </motion.div>
  );
}

